 static Object c(Object o,String n,Object...a){return R.call(o,n,a);}static Object type(String n){return R.type(n);}static Object component(String n){return R.get(type("net.minecraft.core.component.DataComponents"),n);}static Object registry(){return R.get(type("net.minecraft.core.registries.BuiltInRegistries"),"ITEM");}
 static String id(Object s){return c(registry(),"getKey",c(s,"getItem")).toString();}public static int tier(Object s){String id=id(s);for(int i=1;i<TYPES.length;i++)if(id.equals("flashlight:"+TYPES[i])||id.equals("flashlight:"+TYPES[i]+"_off"))return i;return 0;}
 public static boolean light(Object s){String id=id(s);for(String t:TYPES)if(id.equals("flashlight:"+t)||id.equals("flashlight:"+t+"_off"))return true;return false;}public static boolean on(Object s){return light(s)&&!id(s).endsWith("_off");}
 static Object tag(Object s){Object d=c(s,"getOrDefault",component("CUSTOM_DATA"),R.get(type("net.minecraft.world.item.component.CustomData"),"EMPTY"));return c(d,"copyTag");}
 public static int remaining(Object s){Object t=tag(s);return Math.max(0,Math.min(CAPACITY[tier(s)],((Number)c(t,"getInt","FlashTicks4")).intValue()));}
 public static void charge(Object s,int n){Object t=tag(s);c(t,"putInt","FlashTicks4",Math.max(0,Math.min(CAPACITY[tier(s)],n)));c(s,"set",component("CUSTOM_DATA"),c(type("net.minecraft.world.item.component.CustomData"),"of",t));}
 static Object stack(String id){Object item=c(registry(),"get",c(type("net.minecraft.resources.ResourceLocation"),"parse",id));return R.make("net.minecraft.world.item.ItemStack",item,1);}
