 static Object hand(String n){return R.get(type("net.minecraft.world.InteractionHand"),n);}static boolean client(Object e){return Boolean.TRUE.equals(R.get(c(e,"level"),"isClientSide"));}
 static void message(Object e,String key){c(e,"displayClientMessage",c(type("net.minecraft.network.chat.Component"),"translatable",key,new Object[0]),true);}
